mapper.select:
SELECT 
FROM pet_daily_saying_assignments
WHERE account_id = #{accountId}
  AND assignment_id = #{assignmentId}

mapper.update:
UPDATE pet_daily_saying_assignments
SET status = 'READ',
    read_at = #{readAt},
    read_server_date = #{readServerDate},
    greeting_reward_applied = #{greetingRewardApplied},
    greeting_intimacy_delta = #{greetingIntimacyDelta}
WHERE account_id = #{accountId}
  AND assignment_id = #{assignmentId}
  AND status = 'UNREAD'

mapper.select:
SELECT 
FROM pet_daily_saying_assignments
WHERE account_id = #{accountId}
  AND status = 'READ'
ORDER BY read_at DESC
LIMIT #{limit}

SELECT content_id
FROM pet_daily_saying_assignments
WHERE account_id = #{accountId}
ORDER BY assigned_at DESC
LIMIT #{limit}
